  finishBuild(verts, faces) {
    try {
      const saved = JSON.parse(localStorage.getItem(this.sculptKey()) || 'null');
      if (saved && saved.v && saved.f) {
        verts.length = 0; saved.v.forEach(s => verts.push({ x: s[0], y: s[1], z: s[2] }));
        faces.length = 0; saved.f.forEach(f2 => faces.push(f2));
        this.anchors = new Set(saved.a || []);
      } else { this.anchors = new Set(); }
    } catch (err) { this.anchors = new Set(); }
    this.selection = new Set();
    this.verts = verts; this.faces = faces;
    this.pts = verts;
    this.cols = null;
    this.computeEdges();
    this.computeFrame();
  }

  // per-model framing: fit projection scale/center to the mesh's y-extent
  computeFrame() {
    let lo = 1e9, hi = -1e9;
    for (const v of this.verts) { if (v.y < lo) lo = v.y; if (v.y > hi) hi = v.y; }
    this.frame = { span: Math.max(120, (hi - lo) * 1.18), mid: (hi + lo) / 2 };
  }

