      // bridge + brow to muzzle
      [2, 17, 3], [3, 17, 24], [17, 18, 24], [18, 28, 24], [18, 19, 28],
      // muzzle + nose + nostril
      [3, 24, 4], [4, 24, 25], [4, 25, 26], [4, 26, 5], [5, 26, 6],
      [6, 26, 27], [26, 25, 27], [6, 27, 7], [7, 27, 23], [7, 23, 8],
      // cheeks + jaw
      [19, 20, 21], [19, 21, 28], [28, 21, 27], [21, 23, 27], [21, 22, 23], [22, 8, 23],
      [22, 9, 8],
      // back of skull / neck
      [0, 13, 29], [0, 29, 14], [14, 29, 15], [15, 29, 30], [29, 13, 12], [29, 12, 30],
      [15, 30, 20], [20, 30, 31], [30, 12, 11], [30, 11, 31], [20, 31, 21], [21, 31, 32],
      [31, 11, 10], [31, 10, 32], [21, 32, 22], [22, 32, 9], [32, 10, 9],
      // ears — big blades, front + back + base
      [33, 35, 36], [33, 36, 40], [40, 36, 37], [40, 37, 39], [39, 37, 38],
      [34, 36, 35], [34, 37, 36], [34, 38, 37],
      [0, 33, 14], [14, 33, 35], [14, 35, 29], [29, 35, 34]
