  // shared view angles: drag/momentum + optional auto-sway + optional mouse-follow
  viewZoom() { return Math.max(0.2, Math.min(5, ((this._fxView || {}).zoom ?? this.props.zoom ?? 1) * (this._wheelZoom ?? 1))); }

