      line: this.hexRgb(this.props.lineColor ?? '#4dff88'),
      face: this.hexRgb(this.props.faceColor ?? '#39e28e'),
      fx: this.hexRgb(this.props.fxColor ?? '#4dff88'),
      strike: this.hexRgb(this.props.strikeColor ?? '#4dff88'),
