      if (w * dark >= 0.25 && maxE > minEdge) {
        const ab = mid(a, b), bc = mid(b, c2), ca = mid(c2, a);
        out.push([a, ab, ca], [ab, b, bc], [ca, bc, c2], [ab, bc, ca]);
      } else out.push(f);
