      togglePaintDir: () => this.setState(s => ({ paintDir: -s.paintDir })),
      paintDirLabel: this.state.paintDir > 0 ? '▲ OUT' : '▼ IN',
      paintBtnStyle: this.state.brushMode === 'paint'
