          body += `<polygon points="${px(P[fc[0]].sx)},${px(P[fc[0]].sy)} ${px(P[fc[1]].sx)},${px(P[fc[1]].sy)} ${px(P[fc[2]].sx)},${px(P[fc[2]].sy)}" fill="rgb(${r2},${g},${b2})" fill-opacity="${faceA}" stroke="rgb(${r2},${g},${b2})" stroke-opacity="${faceA}" stroke-width="0.8"/>`;
